static inline struct llist_item * llist_insert_sorted_unique ( struct llist * list , const struct object_id * oid , struct llist_item * hint ) { struct llist_item * prev = NULL , * l ; l = ( hint == NULL ) ?list -> front : hint ; while ( l ) { int cmp = oidcmp ( & l -> oid , oid ) ; if ( ! cmp ) { return l ; } prev = l ; l = l -> next ; } return llist_insert_back ( list , oid -> hash ) ; } 